#!/usr/bin/env python3
"""Produce source-faithful shot manifest from verified Piper sentence timing."""
import argparse,json
from pathlib import Path
SCENES={
1:"Title card: Chapter One",2:"Epigraph: Tirung mountains and distant forests; text card, not present-day action",3:"Epigraph attribution: Kerrick, Chronicles of Tarrvania",4:"Alexander's name card",5:"Inside a sweltering, overcrowded metal truck; Alexander exhausted after five days",6:"Alexander struggling to move through fatigue and nausea",7:"Armed kidnappers enter the truck twice daily",8:"Captives avert their eyes from the kidnappers",9:"About ten prisoners huddled together in the truck",10:"Red-haired broad-shouldered Eugene in glasses attempts conversation",11:"Language barrier between Alexander and Eugene",12:"Failed gestures in the cramped truck",13:"Alexander withdraws into silence",14:"Alexander reflects on his past",15:"Flashback: childhood orphanage, Alexander learning to adapt",16:"Alexander remembers his unfulfilled hopes",17:"Flashback: Alexander and Kira at the orphanage",18:"Flashback: Alexander and Kira growing up together",19:"Flashback: Alexander and Kira's contrasting personalities",20:"Flashback: Alexander and Kira's close bond",21:"Flashback: Alexander leaving training and seeing Kira by a car",22:"Five strong men in unusual uniforms at the parking lot",23:"Kira argues with the men; one injects her",24:"Alexander fights several abductors, then is struck from behind",25:"Alexander awakens in the truck",26:"Five days trapped inside the hot metal compartment",27:"At dawn the kidnappers enter again",28:"First captor: slicked-back dark hair and cruel expression",29:"Alexander notices a sword and scabbard",30:"Second captor: masked face with dark brown eyes",31:"Alexander wonders whether the swords are real",32:"Second captor holds a long container; first checks a folder",33:"Thin prisoner on Alexander's left moves and touches his arm",34:"Kidnappers turn sharply toward the movement",35:"Sudden silence before violence",36:"Captor stabs the prisoner in the chest with a sword",37:"Blood on the truck floor",38:"Alexander freezes in shock at the death",39:"Alexander's internal question to himself",40:"Horrified prisoners react; the victim collapses",41:"Captor pulls out sword; other captor injects Alexander in the neck",42:"Alexander's senses suddenly sharpen",43:"First captor consults the folder and begins speaking",44:"Captor reads Alexander's details and calls him 'лишний'",45:"Alexander silently seethes as captor turns toward Eugene",46:"Captor reads Eugene's details and calls him redhead or botanist",47:"Second captor interjects that 'Рыжий' is easier to remember",48:"First captor reads Inigo's record and mentions sword skills",49:"Inigo receives final injection; second captor leaves",50:"First captor announces destination and the 'extra' prisoners",51:"Captor exits with a toothpick in his mouth",52:"Truck interior returns to half-darkness",53:"Truck starts moving; Eugene begins to speak",54:"Eugene asks whether the others understood the captor",55:"Alexander turns to shaking Eugene; dead prisoner remains nearby",56:"Eugene introduces himself to Alexander",57:"Alexander quietly says his name, jaw aching",58:"Inigo introduces himself from across the truck",59:"Inigo appears frightened and has a slight accent",60:"Alexander worries about Kira and the armed kidnappers",61:"Oil lamp trembles abruptly",62:"Lamp flame turns green and then violet",63:"Air seems to thicken; prisoners struggle to breathe",64:"Prisoners cough; one scratches his bloody face and laughs",65:"Alexander cautiously looks back at the lamp",66:"Lamp burns with its ordinary yellow flame",67:"Truck jolts and stops"}
def main():
 p=argparse.ArgumentParser();p.add_argument("--timing",default="output/piper_chapter01/timing.json");p.add_argument("--output",default="output/piper_chapter01/shot_manifest.json");a=p.parse_args()
 d=json.loads(Path(a.timing).read_text(encoding="utf8"));group={}
 for seg in d["segments"]:group.setdefault(seg["line"],[]).append(seg)
 missing=set(group)-set(SCENES)
 if missing:raise SystemExit("Unmapped chapter lines: "+str(sorted(missing)))
 shots=[]
 for line,segs in sorted(group.items()):
  shots.append({"shot":len(shots)+1,"source_line":line,"start":segs[0]["start"],"end":segs[-1]["end"],"visual":SCENES[line],"voices":sorted(set(x["speaker"] for x in segs)),"status":"illustration_needed"})
 Path(a.output).write_text(json.dumps({"chapter":1,"total_duration":d["duration"],"shots":shots},ensure_ascii=False,indent=2),encoding="utf8")
 print("Generated",len(shots),"source-faithful timed shots")
if __name__=="__main__":main()
